        public static Dictionary<string, Dictionary<string, HashSet<int>>> GetZonesFromFile()
        {
            try
            {
                var filePath = "ZoneDefinitions.json";
                if (!System.IO.File.Exists(filePath))
                    return DefaultZones;

                var json = System.IO.File.ReadAllText(filePath);
                JSONArray jsonArray = JSON.Parse(json).AsArray;
                var result = new Dictionary<string, Dictionary<string, HashSet<int>>>();
                foreach (var item in jsonArray)
                {
                    var sceneName = ((JSONNode)item)["Name"].Value;
                    var zones = ((JSONNode)item)["Zones"].AsArray;
                    result[sceneName] = new Dictionary<string, HashSet<int>>();
                    foreach (var zone in zones)
                    {
                        var zoneName = ((JSONNode)zone)["Name"].Value;
                        var nodes = ((JSONNode)item)["Nodes"].AsArray;
                        result[sceneName][zoneName] = new HashSet<int>();
                        foreach (var nodeId in nodes)
                        {
                            result[sceneName][zoneName].Add(int.Parse(((JSONNode)nodeId).Value));
                        }
                    }
                }
                return result;
        }
            catch
            {
                return DefaultZones;
            }
}

